function capacityWindow(){
 const now=iso(),hh=Number(now.slice(11,13)),mm=Number(now.slice(14,16)),minutes=hh*60+mm;
 const toMinutes=v=>Number(v.slice(0,2))*60+Number(v.slice(3,5));
 const startText=now.slice(0,14)+String(Math.floor(mm/15)*15).padStart(2,'0')+':00+07:00';
 const start=Date.parse(startText),end=start+15*60000;
 return {start,end,active:minutes>=toMinutes(s.capacity.start)&&minutes<toMinutes(s.capacity.end),
 count:s.orders.filter(o=>{const t=Date.parse(o.confirmed_at);return t>=start&&t<end;}).length};
}
